    {
      "severity": "high",
      "path": "scripts/verify-dev-dx-audit.py",
      "issue": "G-07 is a false diagnostic finding caused by incorrect selectors. The saved screenshot visibly shows a red gutter marker and error underline on line 18. The helper searches for .cm-lintMarker, while the installed package renders .cm-lint-marker and .cm-lintRange.",
      "expected": "Correct the diagnostic observation, regenerate evidence, and remove the unsupported missing-marker defect and its implementation gate from both reports.",
      "evidence": "scripts/verify-dev-dx-audit.py:704–718; node_modules/@codemirror/lint/dist/index.js:88 and :767; docs/research/evidence/developer-dx-audit-2026-09-13/interactive-diagnostics.png; research report:243–250, :460–468 and :552–554."
